// Differential checks of StringWalk.js against Lean, generated by leanscript --check
import * as M from "./StringWalk.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test3(\"\", 0n)", () => M.test3("", 0n), "0", false);
check("test3(\"\", 2n)", () => M.test3("", 2n), "1", false);
check("test3(\"a\", 1n)", () => M.test3("a", 1n), "1", false);
check("test3(\"hello world\", 0n)", () => M.test3("hello world", 0n), "0", false);
check("test3(\"\", 13n)", () => M.test3("", 13n), "78", false);
check("test3(\"a\", 5n)", () => M.test3("a", 5n), "15", false);
check("test3(\"hello world\", 2n)", () => M.test3("hello world", 2n), "23", false);
check("test3(\"héllo, wörld\", 1n)", () => M.test3("héllo, wörld", 1n), "14", false);
check("test3(\"abcabc\", 0n)", () => M.test3("abcabc", 0n), "0", false);
check("test3(\"hello world\", 13n)", () => M.test3("hello world", 13n), "221", false);
check("test3(\"héllo, wörld\", 5n)", () => M.test3("héllo, wörld", 5n), "80", false);
check("test3(\"abcabc\", 2n)", () => M.test3("abcabc", 2n), "13", false);
check("test3(\"abcabc\", 13n)", () => M.test3("abcabc", 13n), "156", false);

console.log(`StringWalk.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
